function enhanceModal(root=document.querySelector('#modal')){if(!root)return;const panel=root.querySelector('.modal');if(!panel||panel.dataset.a11yReady==='1')return;panel.dataset.a11yReady='1';state.modalReturnFocus=state.modalReturnFocus||document.activeElement;panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.tabIndex=-1;const title=panel.querySelector('.modal-head b,.modal-head h2,.modal-head h3');if(title){if(!title.id)title.id=`fs-dialog-${Date.now()}-${Math.random().toString(16).slice(2)}`;panel.setAttribute('aria-labelledby',title.id)}queueMicrotask(()=>{const first=panel.querySelector('input:not([type=hidden]):not([disabled]),select:not([disabled]),textarea:not([disabled]),button:not([disabled]),a[href]');(first||panel).focus()})}
