function syncSidebarPosition(){const nav=document.querySelector('.sidebar-nav-scroll');if(!nav||nav.dataset.scrollReady==='1')return;nav.dataset.scrollReady='1';const saved=Number(sessionStorage.getItem('fs-sidebar-scroll')||0);nav.scrollTop=saved;const active=nav.querySelector('.nav-item.active');if(active){const aTop=active.offsetTop,aBottom=aTop+active.offsetHeight,vTop=nav.scrollTop,vBottom=vTop+nav.clientHeight;if(aTop<vTop+8)nav.scrollTop=Math.max(0,aTop-18);else if(aBottom>vBottom-8)nav.scrollTop=Math.max(0,aBottom-nav.clientHeight+24)}sessionStorage.setItem('fs-sidebar-scroll',String(nav.scrollTop));nav.addEventListener('scroll',()=>sessionStorage.setItem('fs-sidebar-scroll',String(nav.scrollTop)),{passive:true})}
