async function boot(){try{const [me,pub]=await Promise.all([api('/api/auth/me'),api('/api/public/bootstrap')]);state.public=pub;if(me){state.me=me.user;state.prefs=me.preferences;state.csrf=me.csrfToken;applyTheme(me.preferences?.theme||'system');try{state.uiCounts=await api('/api/ui-counts')}catch{}connectLive()}else applyTheme(localStorage.getItem('fs-theme')||'system')}catch(e){console.error(e)}bindGlobal();render()}
async function refreshUiCounts(){if(!state.me)return;try{state.uiCounts=await api('/api/ui-counts');paintUiBadges()}catch{}}
function paintUiBadges(){const m=Number(state.uiCounts?.unreadMessages||0),n=Number(state.uiCounts?.unreadNotifications||0);$$('[data-ui-badge=messages]').forEach(x=>{x.textContent=m>99?'99+':String(m);x.hidden=!m});$$('[data-ui-badge=notifications]').forEach(x=>{x.textContent=n>99?'99+':String(n);x.hidden=!n})}
function paintTypingIndicator(){const el=$('#message-typing-indicator');if(!el)return;const names=[...state.typingUsers.values()].map(x=>x.name);el.hidden=!names.length;el.textContent=names.length?`${names.slice(0,2).join(', ')}${names.length>2?` +${names.length-2}`:''} ${names.length===1?'is':'are'} typing…`:''}
function applyTheme(pref){state.theme=pref;localStorage.setItem('fs-theme',pref);const actual=pref==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):pref;document.documentElement.dataset.theme=actual;document.querySelector('meta[name=theme-color]')?.setAttribute('content',actual==='dark'?'#0b1112':'#f3f5f1')}
