function publicNav(active=''){const actions=state.me?`<a class="btn primary sm" href="/app" data-link>Open dashboard</a>`:`<a class="btn ghost sm" href="/auth/sign-in" data-link>Sign in</a><a class="btn primary sm" href="/auth/sign-up" data-link>Start scanning</a>`;return `<header class="public-nav">${logo()}<nav class="public-links" aria-label="Primary"><a ${active==='how'?'class="active"':''} href="/how-it-works" data-link>How it works</a><a ${active==='intel'?'class="active"':''} href="/intelligence" data-link>Intelligence</a><a ${active==='discover'?'class="active"':''} href="/discover" data-link>Discover</a><a ${active==='about'?'class="active"':''} href="/about" data-link>About</a></nav><div class="public-actions">${actions}</div></header>`}
