async function renderCookingJournal(){const rows=await api('/api/cooking-journal');app.innerHTML=appShell(`${pageHead('Cooking journal','Remember what you actually cooked, what changed, and what you would make again.','<a class="btn primary" href="/app/recipes" data-link>Find a recipe</a>')}<section class="journal-intro"><div><span class="micro">COOKING MEMORY</span><h2>${rows.length} cooking entr${rows.length===1?'y':'ies'}</h2><p>Finished-dish photos, notes and personal ratings stay private unless you choose to share them as a FoodSnap story.</p></div></section><div class="cooking-journal">${rows.length?rows.map(x=>`<article>${x.photo_url?`<img src="${esc(x.photo_url)}" alt="${esc(x.title)}">`:'<div class="journal-placeholder">FS</div>'}<div><span class="micro">${esc(x.cooked_on)}${x.rating?` · ${'★'.repeat(x.rating)}`:''}</span><h3>${esc(x.title)}</h3>${x.note?`<p>${esc(x.note)}</p>`:''}<div class="row wrap">${x.href?`<a class="btn ghost sm" href="${esc(x.href)}" data-link>Open recipe</a>`:''}<button class="btn ghost sm" data-action="share-cooking-log" data-id="${x.id}" data-title="${esc(x.title)}">Share as food story</button><button class="btn danger sm" data-action="delete-cooking-log" data-id="${x.id}">Delete</button></div></div></article>`).join(''):empty('Nothing cooked yet','Mark a recipe as cooked and your notes will appear here.','Browse recipes','/app/recipes')}</div>`,'journal','Cooking journal')}

function messageShareHref(m){if(m.share_type==='food')return `/app/foods/${m.share_id}`;if(m.share_type==='recipe')return `/app/recipes/${m.share_id}`;if(m.share_type==='user_recipe')return `/app/my-recipes/${m.share_id}`;if(m.share_type==='collection')return `/app/collections/${m.share_id}`;if(m.share_type==='post')return `/app/posts/${m.share_id}`;if(m.share_type==='meal_plan')return `/app/planner?plan=${m.share_id}`;return ''}
