function openGroupMemberActions(btn){const gid=Number(btn.dataset.groupId),uid=Number(btn.dataset.userId),role=btn.dataset.role,name=btn.dataset.name;closeMessageActionMenu();const menu=document.createElement('div');menu.className='message-action-popover group-member-popover';menu.innerHTML=`<button data-action="set-group-role" data-group-id="${gid}" data-user-id="${uid}" data-role="${role==='admin'?'member':'admin'}"><span>♙</span><b>${role==='admin'?'Make member':'Make admin'}</b></button><button data-action="transfer-group-owner" data-group-id="${gid}" data-user-id="${uid}" data-name="${esc(name)}"><span>★</span><b>Transfer ownership</b></button><button class="danger" data-action="remove-group-member" data-group-id="${gid}" data-user-id="${uid}" data-name="${esc(name)}"><span>×</span><b>Remove from group</b></button>`;document.body.appendChild(menu);const r=btn.getBoundingClientRect(),mw=menu.offsetWidth,mh=menu.offsetHeight;menu.style.left=`${Math.min(innerWidth-mw-10,Math.max(10,r.right-mw))}px`;menu.style.top=`${Math.max(10,Math.min(innerHeight-mh-10,r.bottom+6))}px`}
async function openStarredMessages(){const rows=await api('/api/messages/starred');document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal starred-message-modal" role="dialog" aria-modal="true" aria-labelledby="starred-title"><div class="modal-head"><div class="modal-title-block"><span class="micro">MESSAGES</span><h2 id="starred-title">Starred messages</h2><p>Your private shortcuts to important food conversations.</p></div><span class="spacer"></span><button class="icon-btn" data-action="close-modal">×</button></div><div class="modal-body starred-message-list">${rows.length?rows.map(x=>`<button type="button" class="starred-message-row" data-action="open-starred-message" data-conversation-id="${x.conversation_id}" data-id="${x.id}"><span>★</span><div><b>${esc(x.body||'Shared FoodSnap content')}</b><small>${esc(x.is_group?x.title:`@${x.username}`)} · ${fmtDate(x.created_at)}</small></div><i>→</i></button>`).join(''):empty('No starred messages','Use the message menu to star anything you want to find quickly.')}</div></section></div>`);enhanceModal()}
function openMessageReport(id){closeMessageActionMenu();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="report-message-title"><div class="modal-head"><div class="modal-title-block"><span class="micro">COMMUNITY SAFETY</span><h2 id="report-message-title">Report message</h2><p>Reports are reviewed by FoodSnap moderation.</p></div><span class="spacer"></span><button class="icon-btn" data-action="close-modal">×</button></div><form id="message-report-form" data-id="${id}" class="modal-body stack"><div class="field"><label>Reason</label><select class="select" name="reason"><option>Spam or misleading content</option><option>Harassment or bullying</option><option>Unsafe or inappropriate media</option><option>Impersonation</option><option>Other</option></select></div><div class="field"><label>Details <small>optional</small></label><textarea class="textarea" name="detail" rows="4" maxlength="1000"></textarea></div><div class="form-actions"><button type="button" class="btn ghost" data-action="close-modal">Cancel</button><button class="btn danger">Submit report</button></div></form></section></div>`);enhanceModal()}

