async function createCollection(){const cuisines=state.public?.cuisines||[];document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal" style="width:min(600px,calc(100vw - 30px))"><div class="modal-head"><b>New collection</b><span class="spacer"></span><button class="icon-btn" data-action="close-modal">×</button></div><form id="collection-form" class="modal-body stack"><div class="field"><label>Name</label><input class="input" name="name" maxlength="80" required placeholder="e.g. Lagos ideas"></div><div class="field"><label>Description</label><textarea class="textarea" name="description" maxlength="300" placeholder="What belongs here?"></textarea></div><div class="form-grid"><div class="field"><label>Collection type</label><select class="select" name="collectionType"><option value="manual">Manual</option><option value="smart">Smart / rule-based</option></select></div><div class="field"><label>Visibility</label><select class="select" name="visibility"><option value="private">Private</option><option value="public">Public / shareable</option></select></div></div><div class="smart-rule-fields"><span class="micro">OPTIONAL SMART RULES</span><div class="form-grid"><div class="field"><label>Cuisine</label><select class="select" data-searchable name="ruleCuisine"><option value="">Any cuisine</option>${cuisines.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Food type</label><input class="input" name="ruleCategory" placeholder="e.g. Main dish"></div></div><label class="check-chip"><input type="checkbox" name="ruleSaved" value="1"><span>Only foods I saved</span></label></div><div class="field"><label>Cover image URL <span class="muted">optional</span></label><input class="input" name="coverUrl" placeholder="https://..."></div><div class="form-actions"><button class="btn primary">Create collection</button></div></form></section></div>`)}

async function openOrganize(id){const [tags,scan,collections]=await Promise.all([api('/api/library/tags'),api(`/api/scans/${id}`),api('/api/collections')]);const selected=new Set(scan.libraryTags.map(t=>t.id));document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal" style="width:min(560px,calc(100vw - 30px))"><div class="modal-head"><b>Organize ${esc(scan.scan_code)}</b><span class="spacer"></span><button class="icon-btn" data-action="close-modal">×</button></div><form id="organize-form" data-scan-id="${id}" class="modal-body stack"><div><span class="micro">LIBRARY TAGS</span><div class="check-grid" style="margin-top:10px">${tags.length?tags.map(t=>`<label class="check-chip"><input type="checkbox" name="tagIds" value="${t.id}" ${selected.has(t.id)?'checked':''}><span>${esc(t.name)}</span></label>`).join(''):'<span class="muted">No tags yet.</span>'}</div></div><div class="field"><label>Create a new tag</label><input class="input" name="newTag" maxlength="40" placeholder="e.g. Weeknight ideas"></div><div class="field"><label>Add to collection</label><select class="select" name="collectionId" data-searchable><option value="">No collection</option>${collections.map(c=>`<option value="${c.id}">${esc(c.name)} (${c.item_count})</option>`).join('')}</select><small class="muted">Create collections from the Library header, then organize scans into them here.</small></div><div class="form-actions"><button class="btn primary">Save organization</button></div></form></section></div>`)}
function openCook(){if(!state.cook)return;document.querySelector('#cook-root')?.remove();state.cook.index=0;document.body.insertAdjacentHTML('beforeend','<div id="cook-root"></div>');paintCook()}
function paintCook(){const root=$('#cook-root');if(!root||!state.cook)return;const r=state.cook.recipe,i=state.cook.index,servings=state.cook.servings||r.servings,factor=servings/r.servings;root.innerHTML=`<section class="cook-mode"><div class="cook-top"><div><span class="micro">COOK MODE</span><b style="display:block">${esc(r.title)}</b><small>${servings} serving${servings===1?'':'s'}</small></div><div class="row"><button class="btn cook-wake" data-action="cook-wake">Keep screen awake</button><button class="icon-btn" data-action="close-cook" aria-label="Close cook mode">×</button></div></div><div class="cook-layout"><aside class="cook-checklist"><span class="micro">INGREDIENT CHECKLIST</span>${r.ingredients.map((x,ix)=>`<label><input type="checkbox" data-action="cook-check" data-index="${ix}" ${state.cook.checked?.has(ix)?'checked':''}><span><b>${esc(x[0])}</b><small>${esc(scaleQuantity(x[1],factor))}</small></span></label>`).join('')}</aside><div class="cook-step"><div><div class="num">STEP ${String(i+1).padStart(2,'0')} / ${String(r.steps.length).padStart(2,'0')}</div><h2>${esc(r.steps[i])}</h2></div></div></div><div class="cook-actions"><button class="btn ghost" data-action="cook-prev" ${i===0?'disabled':''}>Previous</button><button class="btn primary" data-action="cook-next">${i===r.steps.length-1?'Finish':'Next step'}</button></div></section>`}

function openTwoFactorSetup(data){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal security-modal" role="dialog" aria-modal="true" aria-labelledby="twofa-title"><div class="modal-head"><div class="modal-title-block"><span class="micro">ACCOUNT SECURITY</span><h2 id="twofa-title">Set up two-factor authentication</h2><p>Add FoodSnap to any TOTP authenticator app.</p></div><span class="spacer"></span><button class="icon-btn" data-action="close-modal">×</button></div><form id="twofa-enable-form" class="modal-body stack"><div class="security-secret"><span class="micro">SECRET KEY</span><code>${esc(data.secret)}</code><button type="button" class="btn ghost sm" data-action="copy-text" data-copy="${esc(data.secret)}">Copy</button></div><p class="muted">In Google Authenticator, Microsoft Authenticator, 1Password or another TOTP app, add an account manually with this secret. FoodSnap uses 6-digit codes that refresh every 30 seconds.</p><div class="field"><label>Current code</label><input class="input" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="123456" required></div><button class="btn primary">Verify and enable</button></form></section></div>`);enhanceModal()}
function openTwoFactorDisable(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal security-modal" role="dialog" aria-modal="true" aria-labelledby="twofa-disable-title"><div class="modal-head"><div class="modal-title-block"><span class="micro">ACCOUNT SECURITY</span><h2 id="twofa-disable-title">Disable two-factor authentication</h2><p>Confirm with your current authenticator code.</p></div><span class="spacer"></span><button class="icon-btn" data-action="close-modal">×</button></div><form id="twofa-disable-form" class="modal-body stack"><div class="field"><label>Authenticator code</label><input class="input" name="code" inputmode="numeric" maxlength="6" required></div><button class="btn danger">Disable 2FA</button></form></section></div>`);enhanceModal()}

async function openSearch(){if(!state.me)return;document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal search-modal" role="dialog" aria-modal="true" aria-label="Search FoodSnap"><div class="modal-head"><span>⌕</span><input id="modal-search" class="input" placeholder="Search foods, people, stories, cuisines and more" autofocus><button class="icon-btn" data-action="close-modal">×</button></div><div id="modal-results" class="modal-body">${empty('Search your FoodSnap','Find foods, people, Food Stories, creator recipes, cuisines, collections and your own scans.')}</div></section></div>`);enhanceModal();const input=$('#modal-search');input.focus();const draw=async()=>{try{const d=await api(`/api/search?q=${encodeURIComponent(input.value)}&limit=30`),box=$('#modal-results');if(!input.value){box.innerHTML=d.recent?.length?`<div class="stack"><span class="micro">RECENT SEARCHES</span>${d.recent.map(x=>`<button class="search-hit" data-action="fill-search" data-query="${esc(x.query)}"><span>↗</span><b>${esc(x.query)}</b></button>`).join('')}</div>`:empty('No recent searches','Search FoodSnap to begin.');return}const hits=[...(d.users||[]).map(x=>({type:'Person',title:x.name,meta:`@${x.username}`,image:x.avatar_url,href:`/app/users/${x.username}`})),...(d.posts||[]).map(x=>({type:'Food story',title:(x.caption||'Food story').slice(0,110),meta:`${x.author?.name||'FoodSnap'} · @${x.author?.username||'foodsnap'}`,image:x.media?.[0]?.file_url||x.linked?.image,href:`/app/posts/${x.id}`})),...(d.cuisines||[]).map(x=>({type:'Cuisine',title:x.name,meta:x.region,image:x.image_url,href:`/app/cuisines/${x.slug}`})),...(d.userRecipes||[]).map(x=>({type:'Creator recipe',title:x.title,meta:`@${x.author?.username||'creator'}`,image:x.cover_url,href:`/app/my-recipes/${x.id}`})),...(d.collections||[]).map(x=>({type:'Collection',title:x.name,meta:`${x.item_count||0} items`,image:x.cover_url,href:`/app/collections/${x.id}`})),...d.foods.map(x=>({type:'Food',title:x.name,meta:x.cuisine_name||'',image:x.image_url,href:`/app/foods/${x.slug}`})),...d.ingredients.map(x=>({type:'Ingredient',title:x.name,meta:'Ingredient',image:x.image_url,href:`/app/ingredients/${x.slug}`})),...d.recipes.map(x=>({type:'Recipe',title:x.title,meta:x.cuisine_name||'',image:x.image_url,href:`/app/recipes/${x.slug}`})),...d.scans.map(x=>({type:'Scan',title:x.title,meta:x.scan_code,image:x.media?.[0]?.file_url||'',href:`/app/scans/${x.id}`}))].slice(0,30);box.innerHTML=hits.length?`<div class="search-results">${hits.map(h=>`<a class="search-hit professional" href="${h.href}" data-link><span class="search-hit-media">${h.image?`<img src="${esc(h.image)}" alt="">`:'FS'}</span><div><span class="micro">${esc(h.type)}</span><b>${esc(h.title)}</b><small>${esc(h.meta||'')}</small></div><span>→</span></a>`).join('')}</div><a class="search-view-all" href="/app/search?q=${encodeURIComponent(input.value)}" data-link>View all search results →</a>`:empty('No matches','Try another food, creator, cuisine, collection, story or scan term.')}catch(e){toast(e.message,'error')}};let t;input.addEventListener('input',()=>{clearTimeout(t);t=setTimeout(draw,180)});draw()}

async function openShareLinks(replace=false){if(replace)closeModal();const rows=await api('/api/share-links'),active=rows.filter(x=>!x.revoked_at&&(!x.expires_at||new Date(x.expires_at)>new Date()));document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal"><div class="modal-head"><b>Shared links</b><span class="spacer"></span><button class="icon-btn" data-action="close-modal">×</button></div><div class="modal-body stack">${active.length?active.map(x=>`<article class="share-link-row"><div><span class="micro">${esc((x.item_type||x.kind).toUpperCase())}</span><b>${esc(x.label||'FoodSnap share')}</b><small>Created ${fmtDate(x.created_at)}${x.expires_at?` · expires ${fmtDate(x.expires_at)}`:' · no expiry'}</small></div><div class="row"><button class="btn ghost sm" data-action="copy-text" data-copy="${esc(x.url)}">Copy</button><button class="btn danger sm" data-action="revoke-share-link" data-kind="${esc(x.kind)}" data-token="${esc(x.token)}">Revoke</button></div></article>`).join(''):empty('No active share links','When you share a scan, recipe or collection, you can manage the link here.')}</div></section></div>`)}
async function openNotifications({cursor=0,type='',append=false}={}){if(!state.me)return;const d=await api(`/api/notifications?limit=30${cursor?`&cursor=${cursor}`:''}${type?`&type=${encodeURIComponent(type)}`:''}`);const row=n=>`<article class="notification-row ${n.read_at?'read':'unread'}" data-notification-id="${n.id}"><a href="${n.link||'#'}" ${n.link?'data-link':''}><span class="notification-dot"></span><div><span class="micro">${esc(String(n.type||'update').replaceAll('_',' '))}</span><b>${esc(n.title)}</b><p>${esc(n.message)}</p><small>${fmtDate(n.created_at)}</small></div></a><div class="notification-actions"><button class="icon-btn" data-action="toggle-notification-read" data-id="${n.id}" data-read="${n.read_at?'1':'0'}" title="${n.read_at?'Mark unread':'Mark read'}">${n.read_at?'○':'✓'}</button><button class="icon-btn" data-action="delete-notification" data-id="${n.id}" title="Delete">×</button></div></article>`;if(append){const box=$('#notification-list');box?.insertAdjacentHTML('beforeend',(d.items||[]).map(row).join(''));$('.notification-load-more')?.remove();if(d.nextCursor)box?.insertAdjacentHTML('afterend',`<button class="btn ghost notification-load-more" data-action="notification-load-more" data-cursor="${d.nextCursor}" data-type="${esc(type)}">Load older notifications</button>`);return}document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal notifications-modal" role="dialog" aria-modal="true" aria-labelledby="notifications-title"><div class="modal-head"><div class="modal-title-block"><span class="micro">ACTIVITY</span><h2 id="notifications-title">Notifications</h2><p>${d.unread||0} unread update${Number(d.unread)===1?'':'s'}.</p></div><span class="spacer"></span><button class="btn ghost sm" data-action="read-notifications">Mark all read</button><button class="icon-btn" data-action="close-modal">×</button></div><div class="notification-filter-tabs"><button class="${!type?'active':''}" data-action="notification-filter" data-type="">All</button>${(d.types||[]).slice(0,8).map(t=>`<button class="${type===t.type?'active':''}" data-action="notification-filter" data-type="${esc(t.type)}">${esc(String(t.type).replaceAll('_',' '))}<span>${t.count}</span></button>`).join('')}</div><div class="modal-body notification-modal-body"><div id="notification-list" class="notification-list">${d.items?.length?d.items.map(row).join(''):empty('Nothing here','FoodSnap updates, messages and process completions will appear here.')}</div>${d.nextCursor?`<button class="btn ghost notification-load-more" data-action="notification-load-more" data-cursor="${d.nextCursor}" data-type="${esc(type)}">Load older notifications</button>`:''}</div></section></div>`);enhanceModal()}

function closeModal(dialogResult=null){if(state.cameraStream){state.cameraStream.getTracks().forEach(t=>t.stop());state.cameraStream=null}const resolver=state.dialogResolve;state.dialogResolve=null;const had=!!document.querySelector('#modal');document.querySelector('#modal')?.remove();document.querySelector('#image-viewer')?.remove();if(had&&state.modalReturnFocus instanceof HTMLElement&&document.contains(state.modalReturnFocus))queueMicrotask(()=>state.modalReturnFocus.focus());state.modalReturnFocus=null;if(resolver)resolver(dialogResult)}

boot();
